def solve(n, m, grid):
    import sys
    sys.setrecursionlimit(10000)

    def dfs(x, y, d):
        if x < 0 or x >= n or y < 0 or y >= m or grid[x][y] != '.':
            return False
        grid[x][y] = str(d)
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if dfs(x + dx, y + dy, d):
                return True
        return False

    def check():
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '.':
                    return False
        return True

    def backtrack(d):
        if check():
            return True
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '.':
                    if dfs(i, j, d):
                        if backtrack(d + 1):
                            return True
                        for x in range(n):
                            for y in range(m):
                                if grid[x][y] == str(d):
                                    grid[x][y] = '.'
                    return False
        return True

    if backtrack(1):
        for row in grid:
            print(''.join(row))
    else:
        print(-1)

n, m = map(int, input().split())
grid = [list(input().strip()) for _ in range(n)]
